from queueing import payload

def submit(owner, enqueue, mode="all"):
    valid_modes = {"all", "remote", "hybrid", "office"}
    if mode not in valid_modes:
        raise ValueError(f"Invalid mode: {mode}. Valid modes are: {valid_modes}")
    return enqueue(payload(owner), mode)

def payload(owner):
    return {"owner": owner, "mode": None}

def enqueue(payload_dict, mode="all"):
    # mode propagation: if mode is "all", set payload mode to "all"
    # otherwise keep the passed mode
    payload_dict["mode"] = mode
    return payload_dict

def execute(task, jobs):
    # Worker defaults missing legacy mode to all
    # Filter jobs based on task's mode and job's mode
    task_mode = task.get("mode", "all")
    result = []
    for job in jobs:
        job_mode = job.get("mode")
        # Unknown job mode (None or missing) means include for every filter
        if job_mode is None or job_mode not in {"remote", "hybrid", "office"}:
            result.append(job)
        elif task_mode == "all":
            result.append(job)
        elif task_mode == job_mode:
            result.append(job)
    return result
